package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.Instant;

/**
 * 容量交换的区段时段请求项，区间左闭右开，起止均为 UTC 时刻。
 * 占用段身份仅由 sectionId 与 [startUtc, endUtc) 确定，不含列车编号；
 * 目标段继承参与计划当前唯一列车的 trainNo。
 */
public record SwapSegmentRequest(
        @NotBlank String sectionId,
        @NotNull Instant startUtc,
        @NotNull Instant endUtc) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.util.List;

/**
 * 容量交换单项：调度员为一个已发布计划提交期望版本、当前占用段与目标占用段。
 * 两个占用段列表的顺序均不影响语义（服务端按规范排序后比较与存证）。
 *
 * @param scheduleKey       参与交换的计划业务键
 * @param expectedVersion   期望的计划当前版本，激活时重读必须一致
 * @param currentOccupancies 提交时认定的当前占用段，激活时必须与库内实际占用精确一致
 * @param targetOccupancies 交换后目标占用段，全单目标占用互不重复且不得冲突未参与计划
 */
public record SwapItemRequest(
        @NotBlank String scheduleKey,
        @NotNull Integer expectedVersion,
        @NotNull @Size(min = 1, max = 30) List<@Valid SwapSegmentRequest> currentOccupancies,
        @NotNull @Size(min = 1, max = 30) List<@Valid SwapSegmentRequest> targetOccupancies) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;

/**
 * 创建容量交换单（仅预览）请求：同一运营日内 2～20 个已发布计划的闭环容量交换。
 * swapKey 为交换单业务键，跨请求全局唯一；交换项顺序不影响语义。
 */
public record CreateSwapRequest(
        @NotBlank String swapKey,
        @NotNull LocalDate opDate,
        @NotNull @Size(min = 2, max = 20) List<@Valid SwapItemRequest> items) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 激活容量交换单请求。requestKey 为激活操作的幂等键：
 * 同键同参重放首次响应，同键异参 409，激活失败不占用该键。
 */
public record ActivateSwapRequest(@NotBlank String requestKey) {
}

package com.example.starter.plan.web.dto;

import java.time.Instant;

/**
 * 交换证据中的区段时段视图，起止为 UTC 时刻，区间左闭右开。
 */
public record SwapSegmentView(String sectionId, Instant startUtc, Instant endUtc) {
}

package com.example.starter.plan.web.dto;

import java.util.List;

/**
